        .outputs = .{ "Out 1", "Out 2", "Out 3", null, null, null, null, null },
        .out_kinds = .{ 3, 3, 3, 0, 0, 0, 0, 0 },
        .color = 0x2f6e6e,
        .cat = 7,
    },
};

/// The type (1..) of a script name, or null.
pub fn typeOf(name: []const u8) ?u32 {
    for (&metas, 1..) |*m, i| {
        if (std.mem.eql(u8, m.name, name)) return @intCast(i);
    }
    return null;
}

/// A type's row, or null (0, or past the last).
pub fn of(t: u32) ?*const Meta {
    return if (t >= 1 and t <= metas.len) &metas[t - 1] else null;
}

const std = @import("std");

test "the catalogue: 42 types, names as graph.s parses them, every row filled" {
    const gops = @import("graphops.zig");
    try std.testing.expectEqual(@as(usize, 42), metas.len);
    for (&metas, 1..) |*m, i| {
        try std.testing.expectEqual(@as(?u32, @intCast(i)), gops.typeIndex(m.name));
        try std.testing.expectEqualStrings(gops.type_titles[i - 1], m.title);
        try std.testing.expect(m.color != 0 and m.cat < cat_names.len);
        for (m.val_kinds, m.values) |k, v| {
            if (k == 1) try std.testing.expect(v != null and m.choices.len > 0);
            if (k == 6) try std.testing.expect(v != null and m.choices2.len > 0);
        }
    }
    try std.testing.expectEqualStrings("Arctan2", metas[6].choices[27]);
    try std.testing.expectEqual(@as(?u32, 42), typeOf("fncall"));
}
